export const dictionaries = { en, es } as const;

export type TranslationVars = Record<string, string | number>;

export const LOCALE: Record<Language, string> = { en: "en-US", es: "es-ES" };

const pluralRules = new Map<Language, Intl.PluralRules>();

function pluralCategory(language: Language, n: number) {
  let rules = pluralRules.get(language);
  if (!rules) pluralRules.set(language, (rules = new Intl.PluralRules(LOCALE[language])));
  return rules.select(n);
}

/** Index just past the brace that closes the one opened at `open`, or -1. */
function closing(text: string, open: number) {
  let depth = 0;
  for (let i = open; i < text.length; i++) {
    if (text[i] === "{") depth++;
    else if (text[i] === "}" && --depth === 0) return i + 1;
  }
  return -1;
}

/** ICU-style `{n, plural, =0 {…} one {# file} other {# files}}`: exact `=n` first, then the language's plural
 * category (Spanish "many" falls back to `other`). `#` is the count in the locale's number format. */
function plurals(text: string, vars: TranslationVars, language: Language) {
  const head = /\{(\w+), plural,/g;
  let out = "";
  let last = 0;
  for (let m = head.exec(text); m; m = head.exec(text)) {
    const end = closing(text, m.index);
    if (end < 0 || !(m[1] in vars)) continue;
    const raw = vars[m[1]];
    const n = typeof raw === "number" ? raw : Number(String(raw).replace(/[^\d.-]/g, ""));
    const branches = new Map<string, string>();
    const body = text.slice(head.lastIndex, end - 1);
    const sel = /\s*(=\d+|zero|one|two|few|many|other)\s*\{/g;
    for (let b = sel.exec(body); b; b = sel.exec(body)) {
      const close = closing(body, sel.lastIndex - 1);
      if (close < 0) break;
      branches.set(b[1], body.slice(sel.lastIndex, close - 1));
      sel.lastIndex = close;
    }
    const chosen = branches.get(`=${n}`) ?? branches.get(pluralCategory(language, n)) ?? branches.get("other") ?? "";
    const shown = typeof raw === "number" ? raw.toLocaleString(LOCALE[language]) : String(raw);
    out += text.slice(last, m.index) + chosen.replace(/#/g, shown);
    last = head.lastIndex = end;
  }
  return out + text.slice(last);
}

/** Replace {name} placeholders and plural blocks; unknown placeholders are left visible rather than dropped. */
export function interpolate(text: string, vars?: TranslationVars, language: Language = "en") {
  if (!vars) return text;
  const expanded = text.includes(", plural,") ? plurals(text, vars, language) : text;
  return expanded.replace(/\{(\w+)\}/g, (match, name: string) => (name in vars ? String(vars[name]) : match));
}

export type Translate = (key: TranslationKey, vars?: TranslationVars) => string;

const translators = new Map<Language, Translate>();

export function translator(language: Language): Translate {
  let t = translators.get(language);
  if (!t) translators.set(language, (t = (key, vars) => interpolate(dictionaries[language][key] ?? en[key], vars, language)));
  return t;
}

export function useT(): Translate {
  return translator(useSettings((s) => s.language));
}
